15→export type FormContext = {
16→  formId: string,
17→};
18→export const FormContext = React.createContext<null | FormContext>(null);
19→export const useFormContext = (): FormContext => {
20→  const formContext = React.use(FormContext);
21→  if (formContext === null) { throw new Error(`Missing FormContext provider`); }
22→  return formContext;
23→};
24→
25→
26→export type FormProps = React.PropsWithChildren<ComponentProps<'form'> & {
27→  /** Whether this component should be unstyled. */
28→  unstyled?: undefined | boolean,
29→  
30→  /** Whether this form should be nestable (i.e. can contain other `<form>` elements). */
31→  nestable?: undefined | boolean,
32→}>;
33→/**
34→ * Top-level form wrapper component.
35→ */
36→export const Form = (props: FormProps) => {
37→  const { unstyled = false, nestable, children, className, ...propsRest } = props;
38→  
39→  const formId = React.useId();
40→  const [wrapperRef, setWrapperRef] = React.useState<null | React.ComponentRef<'div'>>(null);
41→  
42→  // Memoize to keep a stable reference
43→  const context: FormContext = React.useMemo(() => ({ formId }), [formId]);
44→  
45→  const renderForm = ({ children }: { children: React.ReactNode }) => {
46→    return (
47→      <form
48→        // Use POST by default to prevent (potentially sensitive) parameters from being leaked through GET params.
49→        // Note: if `action` is a function, then React overrides `method` anyway (and React complains if it's set).
50→        method={typeof propsRest.action === 'function' ? undefined : 'post'}
51→        {...propsRest}
52→        id={formId} // Do not allow override of `id` (breaks functionality)
53→        onSubmit={(event) => {
54→          // We support client only at the moment, so we want to always prevent default browser form submit behavior.
55→          event.preventDefault();
56→          
