/* Copyright (c) Fortanix, Inc.
|* This Source Code Form is subject to the terms of the Mozilla Public License, v. 2.0. If a copy of
|* the MPL was not distributed with this file, You can obtain one at http://mozilla.org/MPL/2.0/. */

import { classNames as cx, type ComponentProps } from '../../../util/componentUtil.ts';
import * as React from 'react';

import { icons } from '../../../assets/icons/_icons.ts';
import cl from './Icon.module.scss';


export { cl as IconClassNames };

export type IconName = keyof typeof icons;
export const iconNames = new Set(Object.keys(icons) as Array<IconName>);
export const isIconName = (iconName: string): iconName is IconName => {
  return (iconNames as Set<string>).has(iconName);
};

export type Decoration = (
  | { type: 'background-circle' }
);

type EventProps = {
  event: 'warning',
};
const Event = (props: EventProps) => {
  if (props.event !== 'warning') {
    return null;
  }
  const icon: IconName = props.event === 'warning' ? 'warning-filled' : props.event;
  return (
    <Icon icon={icon} className={cl[`bk-icon-event--${icon}`]} />
  );
};

export type IconProps = React.PropsWithChildren<ComponentProps<'svg'> & {
  /** Whether this component should be unstyled. */
  unstyled?: boolean,

  /** The name of the icon to display */
  icon: IconName,

  /** The color to apply to the icon */
  color?: undefined | string,

  /** Visual decoration to apply */
  decoration?: undefined | Decoration,
}>;
export const Icon = Object.assign(
  ({ unstyled, icon, color = 'currentColor', decoration, ...props }: IconProps) => {
    const symbolId = `#baklava-icon-${icon}`;

    return (
      <svg
        role="presentation"
        aria-hidden // https://stackoverflow.com/questions/61048356/why-do-we-use-aria-hidden-with-icons
        {...props}
        className={cx(
          'bk',
          'icon', // Global class name (for generic targeting in CSS)
          { [cl['bk-icon']]: !unstyled },
          { [cl['bk-icon--background-circle']]: decoration?.type === 'background-circle' },
          props.className,
        )}
      >
        <use href={symbolId} fill={color}/>
      </svg>
    );
  }, {
    Event,
  },
);

/* Copyright (c) Fortanix, Inc.
|* This Source Code Form is subject to the terms of the Mozilla Public License, v. 2.0. If a copy of
|* the MPL was not distributed with this file, You can obtain one at http://mozilla.org/MPL/2.0/. */

import { classNames as cx, type ComponentProps } from '../../../util/componentUtil.ts';
import * as React from 'react';

import { IconButton } from '../../actions/IconButton/IconButton.tsx';

import cl from './Tag.module.scss';


export { cl as TagClassNames };

export type TagProps = Omit<ComponentProps<'div'>, 'content' | 'children'> & {
  /** Whether this component should be unstyled. */
  unstyled?: undefined | boolean,

  /** Some content to be displayed inside the tag. */
  content: React.ReactNode,

  /** Callback to remove the tag. If set, display a close icon, otherwise it is hidden. */
  onRemove?: () => void,
};
/**
 * A tag component.
 */
export const Tag = (props: TagProps) => {
  const {
    unstyled = false,
    content = null,
    onRemove,
    ...propsRest
  } = props;

  return (
    <div
      {...propsRest}
      className={cx(
        'bk',
        { [cl['bk-tag']]: !unstyled },
        propsRest.className,
      )}
    >
      <span className={cl['bk-tag__content']}>{content}</span>
      {onRemove &&
        <IconButton onPress={onRemove} icon="cross" label="Remove tag" className={cl['bk-tag__action']}/>
      }
    </div>
  );
};

