22→export const createToastNotifier = (toastStore: ToastStore) => {
23→  const notify = (toast: ToastDescriptor) => {
24→    // If a toast with the same dedupeKey is already active, do not create another one.
25→    if (toastStore.hasActiveDedupeKey(toast)) { return; }
26→    const toastId = toastStore.uniqueId();
27→    toastStore.announceToast(toastId, toast);
28→  };
29→  const notifyVariant = (
30→    variant: BannerVariant,
31→    toast: string | Omit<ToastDescriptor, 'variant'>,
32→    options?: undefined | ToastOptions,
33→  ) => {
34→    const descriptor: ToastDescriptor = typeof toast === 'string'
35→      ? { variant, message: toast, options }
36→      : { ...toast, variant, options: { ...toast.options, ...(options ?? {}) } };
37→    notify(descriptor);
38→  };
39→  return Object.assign(notify, {
40→    info: (toast: string | Omit<ToastDescriptor, 'variant'>, options?: undefined | ToastOptions) =>
41→      notifyVariant('info', toast, options),
42→    warning: (toast: string | Omit<ToastDescriptor, 'variant'>, options?: undefined | ToastOptions) =>
43→      notifyVariant('warning', toast, options),
44→    error: (toast: string | Omit<ToastDescriptor, 'variant'>, options?: undefined | ToastOptions) =>
45→      notifyVariant('error', toast, options),
46→    success: (toast: string | Omit<ToastDescriptor, 'variant'>, options?: undefined | ToastOptions) =>
47→      notifyVariant('success', toast, options),
48→    dismiss: (toastId: ToastId) => {
49→      toastStore.dismissToast(toastId);
50→    },
51→    dismissAll: () => {
52→      toastStore.dismissAllToasts();
53→    },
54→  });
55→};
