 49→  
 50→  /**
 51→   * Whether the button is in "nonactive" state. This is a variant of `disabled`, but instead of completely graying
 52→   * out the button, it only becomes a muted variation of the button's appearance. Nonactive buttons are useful for
 53→   * temporarily states such as while an action is currently ongoing. Nonactive buttons are still focusable.
 54→   */
 55→  nonactive?: undefined | boolean,
 56→  
 57→  /** Time (in ms) after which async actions will trigger a failure */
 58→  asyncTimeout?: number,
